import { supabase } from "../../host/db.js";
import { chatHostHasDatabase } from "../../host/configure.js";
import { WEB_TOOL_UI_SURFACE } from "./surface.js";
async function fetchToolRendererRow(toolName) {
  if (!chatHostHasDatabase()) return null;
  const { data, error } = await supabase.schema("tool").from("ui").select(
    "inline_code, allowed_imports, display_name, results_label, header_subtitle_code, keep_expanded_on_stream"
  ).is("deleted_at", null).eq("tool_name", toolName).eq("surface_name", WEB_TOOL_UI_SURFACE).eq("is_active", true).maybeSingle();
  if (error) {
    console.error(
      `[fetchToolRendererRow] failed to load tool_ui for "${toolName}":`,
      error
    );
    return null;
  }
  if (!data || !data.inline_code) return null;
  const allowedImports = Array.isArray(data.allowed_imports) ? data.allowed_imports.filter(
    (item) => typeof item === "string"
  ) : [];
  return {
    inline_code: data.inline_code,
    allowed_imports: allowedImports,
    display_name: typeof data.display_name === "string" ? data.display_name : null,
    results_label: typeof data.results_label === "string" ? data.results_label : null,
    header_subtitle_code: typeof data.header_subtitle_code === "string" ? data.header_subtitle_code : null,
    keep_expanded_on_stream: data.keep_expanded_on_stream === true
  };
}
export {
  fetchToolRendererRow
};
